(() => {
'use strict';
const c=window.HVT,$=s=>document.querySelector(s),form=$('#postForm');let rows=[],live=new Set(),current=null,preview=false,actor=null,dirty=false,busy=false,loaded=false;
const editor=window.HVTRich.mount($('#postRich'),{label:'Bài viết trang chủ',onChange:()=>{dirty=true}});
const status=(text,error=false)=>{$('#postsStatus').textContent=text;$('#postsStatus').classList.toggle('error',error)};
const rpc=(name,data)=>c.api('/rest/v1/rpc/'+name,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function controls(){form.querySelector('fieldset').disabled=busy||preview;editor.setDisabled(busy||preview);$('#postNew').disabled=busy;$('#postReload').disabled=busy;$('#postHide').disabled=busy||preview||!current||!live.has(current.id)}
function canLeave(){return !dirty||window.confirm('Bài viết có thay đổi chưa lưu. Rời bản đang soạn?')}
function edit(row=null){current=row;form.reset();for(const name of ['title','summary','author','cover_url'])form.elements[name].value=row?.[name]||'';editor.setHTML(row?.body_html||'');dirty=false;$('#postHeading').textContent=row?'Chỉnh sửa bài viết':'Viết bài mới';controls()}
function render(){$('#postList').innerHTML=rows.length?rows.map(r=>`<div class="resource-row"><div><h3>${c.esc(r.title)}</h3><p class="hint">${live.has(r.id)?'Đã đăng · sửa nháp không thay bản công khai':'Bản nháp · chưa công khai'}</p><button class="text-link" type="button" data-edit-post="${c.esc(r.id)}">Mở bản nháp</button></div></div>`).join(''):'<p class="hint">Chưa có bài viết. Bắt đầu từ một điều muốn chia sẻ.</p>'}
async function load(){if(preview){rows=[];live.clear();render();edit();status('Xem trước. Kết nối Supabase để lưu và đăng bài.');return}busy=true;controls();try{rows=await c.api('/rest/v1/home_post_drafts?select=*&order=updated_at.desc&limit=1000');const published=await c.publicApi('/rest/v1/home_posts?select=id&limit=1000');live=new Set(published.map(p=>p.id));loaded=true;render();status('Lưu nháp để viết tiếp. Chỉ khi chọn Đăng lên trang chủ, nội dung mới công khai.')}catch(error){status('Chưa tải được bài viết. Chạy upgrade-profile-posts-ratings.sql. '+error.message,true)}finally{busy=false;controls()}}
form.addEventListener('input',()=>dirty=true);
async function save(publish){if(preview||busy||!form.reportValidity())return;busy=true;controls();status('Đang lưu bài viết…');try{const url=form.elements.cover_url.value.trim();if(url&&!c.https(url))throw Error('Ảnh bìa cần URL HTTPS hợp lệ.');if(publish&&!window.HVTRich.text(editor.getHTML()).trim())throw Error('Nhập nội dung bài viết trước khi đăng.');let coverPath=current?.cover_path||null;if(url&&url!==current?.cover_url)coverPath=null;const file=form.elements.cover_file.files[0];if(file){coverPath=await c.upload('covers',await c.imageFile(file),'jpg')}const result=await rpc('save_home_post',{p_id:current?.id||crypto.randomUUID(),p_expected_version:current?.version||0,p_data:{title:form.elements.title.value.trim(),summary:form.elements.summary.value.trim(),author:form.elements.author.value.trim(),body_html:editor.getHTML(),cover_url:url,cover_path:coverPath}});current=Array.isArray(result)?result[0]:result;dirty=false;form.elements.cover_file.value='';if(publish){await rpc('publish_home_post',{p_id:current.id,p_expected_version:current.version});live.add(current.id)}rows=rows.filter(r=>r.id!==current.id);rows.unshift(current);render();status(publish?'Đã đăng bài lên trang chủ.':'Đã lưu bản nháp; bản công khai giữ nguyên.')}catch(error){status(error.message,true)}finally{busy=false;controls()}}
$('#postSaveDraft').onclick=()=>save(false);form.onsubmit=e=>{e.preventDefault();save(true)};$('#postNew').onclick=()=>{if(canLeave())edit()};$('#postReload').onclick=()=>{if(canLeave()){edit();load()}};
$('#postList').onclick=e=>{const b=e.target.closest('[data-edit-post]');if(b&&canLeave())edit(rows.find(r=>r.id===b.dataset.editPost))};
$('#postHide').onclick=async()=>{if(!current||busy||preview)return;busy=true;controls();try{await c.api('/rest/v1/home_posts?id=eq.'+encodeURIComponent(current.id),{method:'DELETE'});live.delete(current.id);render();status('Đã ẩn bài khỏi trang chủ. Bản nháp vẫn còn để đăng lại.')}catch(error){status(error.message,true)}finally{busy=false;controls()}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
window.HVTPosts={open(next){if(actor!==next.user?.id||preview!==!!next.preview){loaded=false;rows=[];current=null;dirty=false;actor=next.user?.id;preview=!!next.preview;edit()}if(!loaded)load();controls()},lock(){editor.setDisabled(true);form.querySelector('fieldset').disabled=true}};
edit();
})();
